-- Generated by tools/make-update.py from the litprofit repo. Do not edit.
-- Enquiries: invoiced/paid/folder columns, payments in parts, document records.
-- Safe to run more than once. Run in the SQL editor of LitProfit calculator.

-- ==== from migrate-enquiries-5.sql
-- ============================================================
-- MIGRATION 5: the SharePoint register's own columns
-- ============================================================
-- The register's source of truth is the SharePoint list "Litprofit tiekimo
-- užklausos". Its export carries four columns the Power BI extract did not:
--
--   Išstatyta                  -> invoiced_ex_vat   what was invoiced, which is
--                                 not always the price: SK26-100 and SK26-103
--                                 are invoiced at 50 % as advance payments
--   Apmokėta                   -> paid_ex_vat       what arrived, as a figure
--   Aplanko nuoroda            -> folder_url        the job's SharePoint folder
--   Galutinio pristatymo data  -> final_delivery_date
--
-- `paid` stays the boolean the screen toggles; paid_ex_vat is the amount the
-- list recorded. Both are kept because the list has a line paid MORE than it
-- was invoiced (26.6-25.3), and a boolean cannot say so.
--
-- The view is extended with `create or replace`, appending at the end: replace
-- may add columns but not reorder them, and save_enquiry / create_enquiry
-- return `setof enquiries_v`, so dropping the view would take them with it.
-- save_enquiry does not write these columns, so an edit on screen leaves the
-- imported figures as they were.
--
-- Safe to run more than once. Run after migrate-enquiries-4.sql.
begin;

alter table iberia.enquiries add column if not exists invoiced_ex_vat     numeric(14,2);
alter table iberia.enquiries add column if not exists paid_ex_vat         numeric(14,2);
alter table iberia.enquiries add column if not exists folder_url          text;
alter table iberia.enquiries add column if not exists final_delivery_date date;

create or replace view iberia.enquiries_v as
 SELECT id, number, client, description, enquiry_date, sent_to_supplier, supplier,
    quoted_to_client,
    iberia.enquiry_days_unquoted(quoted_to_client, enquiry_date, status) AS days_unquoted,
    status, po_date, cost_ex_vat, price_ex_vat,
    CASE WHEN cost_ex_vat IS NULL THEN NULL::numeric
         ELSE price_ex_vat - cost_ex_vat END AS margin_eur,
    CASE WHEN cost_ex_vat IS NULL OR price_ex_vat = 0::numeric THEN NULL::numeric
         ELSE round((price_ex_vat - cost_ex_vat) / price_ex_vat, 4) END AS margin_pct,
    delivered, paid, paid_date, invoice_no, owner, note, rev, created_at, updated_at, updated_by,
    invoiced_ex_vat, paid_ex_vat, folder_url, final_delivery_date
   FROM iberia.enquiries e
  WHERE iberia.sees_money();

commit;

-- ==== from migrate-enquiry-payments.sql
-- ============================================================
-- PAYMENTS: an invoice paid in parts
-- ============================================================
-- Clients pay in instalments -- an advance, the rest on delivery -- and the
-- register had one tick for "paid" and one amount. A payment is now a row:
-- the day, the share of the invoice in percent, the amount, a note. Either
-- the percent or the amount is typed; the screen works out the other from
-- the order total (the larger of the price and what has been invoiced).
--
-- The enquiry's own paid / paid_ex_vat / paid_date follow the payments, by
-- trigger, so every screen and report that already reads them stays right:
--   paid_ex_vat = the sum of the payments
--   paid        = the sum covers the order total (to the cent)
--   paid_date   = the day of the payment that completed it
--
-- What SharePoint recorded as paid is carried over as one payment per
-- enquiry ("Importuota iš SharePoint"), and an enquiry ticked paid with no
-- amount gets one 100 % payment, so nothing reads as owed that was not.
--
-- Safe to run more than once.
begin;

create table if not exists iberia.enquiry_payments (
  id          uuid primary key default gen_random_uuid(),
  enquiry_id  uuid not null references iberia.enquiries(id) on delete cascade,
  paid_on     date not null default current_date,
  pct         numeric(7,3),
  amount      numeric(14,2) not null check (amount >= 0),
  note        text,
  created_at  timestamptz not null default now(),
  created_by  uuid references auth.users(id) default iberia.admin_uid()
);
create index if not exists enquiry_payments_enq_idx on iberia.enquiry_payments (enquiry_id, paid_on);

alter table iberia.enquiry_payments enable row level security;
drop policy if exists enquiry_payments_read   on iberia.enquiry_payments;
drop policy if exists enquiry_payments_insert on iberia.enquiry_payments;
drop policy if exists enquiry_payments_update on iberia.enquiry_payments;
drop policy if exists enquiry_payments_delete on iberia.enquiry_payments;
create policy enquiry_payments_read   on iberia.enquiry_payments for select to authenticated using (iberia.sees_money());
create policy enquiry_payments_insert on iberia.enquiry_payments for insert to authenticated with check (iberia.sees_money());
create policy enquiry_payments_update on iberia.enquiry_payments for update to authenticated using (iberia.sees_money()) with check (iberia.sees_money());
create policy enquiry_payments_delete on iberia.enquiry_payments for delete to authenticated using (iberia.sees_money());
revoke all on iberia.enquiry_payments from anon;
grant select, insert, update, delete on iberia.enquiry_payments to authenticated;

-- The share is of the whole order: the larger of the price and what has
-- been invoiced. Of the invoice alone, a 50 % advance invoice paid in full
-- read as "paid" while half the order was still to come.
--
-- Enforced BEFORE every update of an enquiry that has payments, so a price
-- or invoice changed later, or a "paid" tick sent by an older screen, cannot
-- leave the row disagreeing with its payments. The payments trigger only
-- touches the row to make that happen.
create or replace function iberia.enquiry_paid_from_payments()
returns trigger language plpgsql security definer set search_path = '' as $$
declare total numeric; last_day date; n int; base numeric;
begin
  select count(*), coalesce(sum(amount), 0), max(paid_on) into n, total, last_day
    from iberia.enquiry_payments where enquiry_id = new.id;
  if n = 0 then return new; end if;
  base := greatest(coalesce(new.invoiced_ex_vat, 0), coalesce(new.price_ex_vat, 0));
  new.paid_ex_vat := case when total > 0 then total end;
  new.paid        := base > 0 and total >= base - 0.01;
  new.paid_date   := case when new.paid then last_day end;
  return new;
end $$;
revoke all on function iberia.enquiry_paid_from_payments() from public, anon;
drop trigger if exists enquiry_paid_from_payments on iberia.enquiries;
create trigger enquiry_paid_from_payments before update on iberia.enquiries
  for each row execute function iberia.enquiry_paid_from_payments();

create or replace function iberia.enquiry_payments_roll()
returns trigger language plpgsql security definer set search_path = '' as $$
declare eid uuid; left_ int;
begin
  eid := coalesce(new.enquiry_id, old.enquiry_id);
  select count(*) into left_ from iberia.enquiry_payments where enquiry_id = eid;
  if left_ = 0 then
    -- the last payment removed: nothing paid any more
    update iberia.enquiries set paid_ex_vat = null, paid = false, paid_date = null,
           updated_at = now(), rev = rev + 1 where id = eid;
  else
    update iberia.enquiries set updated_at = now(), rev = rev + 1 where id = eid;
  end if;
  return null;
end $$;
revoke all on function iberia.enquiry_payments_roll() from public, anon;

drop trigger if exists enquiry_payments_roll on iberia.enquiry_payments;
create trigger enquiry_payments_roll after insert or update or delete on iberia.enquiry_payments
  for each row execute function iberia.enquiry_payments_roll();

-- what was already recorded as paid, carried over once
insert into iberia.enquiry_payments (enquiry_id, paid_on, pct, amount, note)
select e.id, coalesce(e.paid_date, e.po_date, current_date),
       round(100 * e.paid_ex_vat / nullif(greatest(coalesce(e.invoiced_ex_vat, 0), e.price_ex_vat), 0), 3),
       e.paid_ex_vat, 'Importuota iš SharePoint'
  from iberia.enquiries e
 where e.paid_ex_vat > 0
   and not exists (select 1 from iberia.enquiry_payments p where p.enquiry_id = e.id);
insert into iberia.enquiry_payments (enquiry_id, paid_on, pct, amount, note)
select e.id, coalesce(e.paid_date, e.po_date, current_date), 100,
       greatest(coalesce(e.invoiced_ex_vat, 0), e.price_ex_vat), 'Pažymėta kaip apmokėta'
  from iberia.enquiries e
 where e.paid and coalesce(e.paid_ex_vat, 0) = 0 and greatest(coalesce(e.invoiced_ex_vat, 0), e.price_ex_vat) > 0
   and not exists (select 1 from iberia.enquiry_payments p where p.enquiry_id = e.id);

commit;

-- ==== from migrate-enquiry-records.sql
-- ============================================================
-- ENQUIRY RECORDS: what the sales folder says, without the files
-- ============================================================
-- The year's sales folder is a folder per enquiry: quotes, invoices, payment
-- orders, e-mails, photographs -- 9,000 files, 4.6 GB. What the register
-- needs from it is the information, not the files: one row per document with
-- its type, date, number, amount, the other party, the e-mail's subject, and
-- where the file sits on the office disk. ~8,700 rows, a few MB.
--
-- Written only through import_enquiry_records(), which the calculator calls
-- in batches from Documents -> "Import a sales folder" with the manifest made
-- by tools/sales-manifest/. Idempotent: (enquiry_id, sha256) is unique and a
-- row already there is left alone, so the import can be run again.
--
-- Safe to run more than once.
begin;

create table if not exists iberia.enquiry_records (
  id           bigserial primary key,
  enquiry_id   uuid not null references iberia.enquiries(id) on delete cascade,
  sha256       text not null,
  kind         text not null default 'other',
  doc_date     date,
  ref          text,
  amount       numeric(14,2),
  counterparty text,
  title        text,
  detail       text,
  source       text,
  copies       int not null default 1,
  created_at   timestamptz not null default now(),
  unique (enquiry_id, sha256)
);
create index if not exists enquiry_records_enq_idx on iberia.enquiry_records (enquiry_id, doc_date);

alter table iberia.enquiry_records enable row level security;
drop policy if exists enquiry_records_read on iberia.enquiry_records;
create policy enquiry_records_read on iberia.enquiry_records
  for select to authenticated using (iberia.sees_money());
revoke all on iberia.enquiry_records from anon;
grant select on iberia.enquiry_records to authenticated;

create or replace function iberia.import_enquiry_records(p_rows jsonb)
returns int language plpgsql security definer set search_path = '' as $$
declare n int;
begin
  if not iberia.sees_money() then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  insert into iberia.enquiry_records (enquiry_id, sha256, kind, doc_date, ref, amount,
                                      counterparty, title, detail, source, copies)
  select (r->>'enquiry_id')::uuid, r->>'sha256', coalesce(r->>'kind', 'other'),
         nullif(r->>'doc_date', '')::date, nullif(r->>'ref', ''),
         nullif(r->>'amount', '')::numeric, nullif(r->>'counterparty', ''),
         left(r->>'title', 500), left(r->>'detail', 2000), left(r->>'source', 600),
         coalesce(nullif(r->>'copies', '')::int, 1)
    from jsonb_array_elements(p_rows) r
   where nullif(r->>'enquiry_id', '') is not null
  on conflict (enquiry_id, sha256) do nothing;
  get diagnostics n = row_count;
  return n;
end $$;
revoke all on function iberia.import_enquiry_records(jsonb) from public, anon;
grant execute on function iberia.import_enquiry_records(jsonb) to authenticated;

-- the files are not uploaded after all: the bucket goes back to 25 MB

commit;

notify pgrst, 'reload schema';
